const item = $input.first();
const binary = item.binary ? item.binary['resume_file'] : undefined;

// candidate_reference is carried through best-effort only and never
// depended on - candidate_id is generated deterministically below
// instead, since a candidate shouldn't be trusted to self-report their
// own system identifier anyway. (Root-cause note: an earlier round of
// manual curl testing saw this field arrive as null and initially
// mis-diagnosed it as an n8n platform limitation. The actual cause was
// the test harness itself - n8n's rendered form submits multipart field
// names positionally (field-0, field-1, ...) rather than the human
// -readable fieldName configured below, and curl was sending the
// configured name directly. A real submission through n8n's own
// rendered form works correctly regardless of field order, since the
// browser and this workflow's backend both derive field-N from the same
// live form configuration. See CANDOR-02-Build-Log.md for the full
// investigation.)
const candidateReference = (item.json && item.json.candidate_reference) || null;

function rejected(reason) {
  return [{
    json: {
      candidate_id: null,
      resume_filename: binary ? binary.fileName : null,
      candidate_reference_submitted: candidateReference,
      intake_status: 'REJECTED',
      rejection_reason: reason
    }
  }];
}

if (!binary) {
  return rejected('no file was submitted in the resume_file field');
}

const fileName = binary.fileName || 'unknown';
const extension = (binary.fileExtension || '').toLowerCase();
const allowedExtensions = ['txt', 'pdf'];

if (!allowedExtensions.includes(extension)) {
  return rejected(`unsupported file type ".${extension || 'unknown'}" - only .txt and .pdf resumes are accepted`);
}

const byteCount = typeof binary.bytes === 'number' ? binary.bytes : null;
if (byteCount === null) {
  return rejected('could not determine the uploaded file size');
}
if (byteCount === 0) {
  return rejected('the uploaded file is empty (0 bytes)');
}

// Deterministic candidate_id derived from the filename plus the exact
// millisecond the submission was received - does not depend on a field
// the candidate might leave blank, or that this platform version
// currently fails to capture alongside a file upload (see note above).
const safeStem = fileName.replace(/\.[^.]+$/, '').replace(/[^a-zA-Z0-9]+/g, '-').toUpperCase().slice(0, 24);
const candidateId = `INTAKE-${safeStem}-${Date.now()}`;

return [{
  json: {
    candidate_id: candidateId,
    resume_filename: fileName,
    file_extension: extension,
    file_size_bytes: byteCount,
    candidate_reference_submitted: candidateReference,
    intake_status: 'VALID'
  },
  binary: item.binary
}];

const extracted = $input.first().json;
const intake = $('CheckFileBasics').first().json;
const rawText = typeof extracted.text === 'string' ? extracted.text : '';

// --- Step 1: repair 'UTF-8 bytes shown as Windows-1252' mojibake ---
// This is the exact corruption pattern that broke CANDOR-01's
// synthetic-resume-03.txt test (see CANDOR-01-Build-Log.md Results, Run 3).
//
// Approach: UTF-8 multi-byte sequences that get mis-decoded one byte at a
// time as Windows-1252 always start with a small, fixed set of lead
// characters - "Ã" (from a 2-byte C3 xx sequence: Latin-1 Supplement
// letters like é/è/ó), "Â" (from a 2-byte C2 xx sequence: C1
// controls/Latin-1 punctuation, most commonly a non-breaking space), and
// "â€" or "â–" (from a 3-byte E2 80/96 xx sequence: General
// Punctuation - curly quotes, dashes, bullet, ellipsis - or Block
// Elements). Each is repaired by reversing exactly that one corrupted
// character back to its original cp1252 BYTE value and reconstructing the
// true Unicode code point via the same UTF-8 bit math, using ONLY the one
// character immediately following the diagnostic prefix. This only fires
// on these specific, essentially never-coincidental 1-2 character prefix
// sequences, so it cannot corrupt a standalone genuine em dash, curly
// quote, or accented letter elsewhere in the text - unlike an earlier
// whole-string approach (reverting the entire text through one byte
// buffer) which was found, via real testing, to corrupt genuinely correct
// em dashes that happened to share a byte-derived code point with actual
// mojibake elsewhere in the same document.
//
// Known, accepted limitation: a small number of cp1252 byte values are
// themselves undefined (e.g. the byte behind a closing curly quote) and
// render as nothing when mis-decoded, so that specific character is
// consumed by nothing 'visible' - the diagnostic prefix is then left
// exactly as-is rather than guessing (a genuine mojibake continuation
// byte is never literal whitespace in practice, so whitespace right
// after the prefix is treated as "not a continuation - leave it alone"
// rather than eaten and replaced with a wrong character). This trades a
// small amount of missed repair for zero risk of silently merging two
// words together or inventing a wrong symbol.
function buildReverseCp1252Map() {
  const highMap = {
    0x80: 0x20AC, 0x82: 0x201A, 0x83: 0x0192, 0x84: 0x201E, 0x85: 0x2026,
    0x86: 0x2020, 0x87: 0x2021, 0x88: 0x02C6, 0x89: 0x2030, 0x8A: 0x0160,
    0x8B: 0x2039, 0x8C: 0x0152, 0x8E: 0x017D, 0x91: 0x2018, 0x92: 0x2019,
    0x93: 0x201C, 0x94: 0x201D, 0x95: 0x2022, 0x96: 0x2013, 0x97: 0x2014,
    0x98: 0x02DC, 0x99: 0x2122, 0x9A: 0x0161, 0x9B: 0x203A, 0x9C: 0x0153,
    0x9E: 0x017E, 0x9F: 0x0178
  };
  const reverseMap = {};
  for (let b = 0; b <= 0xFF; b++) {
    const cp = highMap[b] !== undefined ? highMap[b] : b;
    reverseMap[cp] = b;
  }
  return reverseMap;
}

function repairMojibake(text) {
  if (!text) return { text, repaired: false, repairedCount: 0 };
  const reverseMap = buildReverseCp1252Map();
  let repairedCount = 0;

  function fix(base, nextChar) {
    if (/\s/.test(nextChar)) return null;
    const b = reverseMap[nextChar.codePointAt(0)];
    if (b === undefined) return null;
    return String.fromCodePoint(base | (b & 0x3F));
  }

  let result = text;
  const prefixRules = [['â€', 0x2000], ['â–', 0x2580], ['Ã', 0x00C0], ['Â', 0x0080]];
  for (const [prefix, base] of prefixRules) {
    const re = new RegExp(prefix + '(.)', 'gu');
    result = result.replace(re, (m, c) => {
      const fixed = fix(base, c);
      if (fixed !== null) { repairedCount++; return fixed; }
      return m;
    });
  }

  return { text: result, repaired: repairedCount > 0, repairedCount };
}

// --- Step 2: strip stray replacement characters (genuinely lost data,
// not repairable - e.g. from invalid byte sequences that can't round-trip
// back to anything meaningful) ---
function stripReplacementChars(text) {
  const count = (text.match(/�/g) || []).length;
  return { text: text.replace(/�/g, ''), count };
}

// --- Step 3: whitespace normalization ---
function normalizeWhitespace(text) {
  return text
    .replace(/ /g, ' ')
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map(line => line.replace(/[ \t]+/g, ' ').trimEnd())
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const step1 = repairMojibake(rawText);
const step2 = stripReplacementChars(step1.text);
const finalText = normalizeWhitespace(step2.text);

return [{
  json: {
    candidate_id: intake.candidate_id,
    resume_filename: intake.resume_filename,
    file_extension: intake.file_extension,
    file_size_bytes: intake.file_size_bytes,
    resume_text: finalText,
    intake_status: 'OK',
    normalization_notes: {
      mojibake_repair_applied: step1.repaired,
      mojibake_repairs_count: step1.repairedCount,
      replacement_chars_stripped: step2.count
    }
  }
}];

// === CANDOR-08 deduplication support (System Review item 27) ===
// Computes a canonical content hash of the already-normalized resume
// text, so CANDOR-08 can later detect "the same resume submitted again"
// independent of filename, candidate_id (always freshly minted), or
// trivial re-encoding/whitespace differences.
//
// Canonicalization is applied ON TOP of NormalizeText's own mojibake
// repair + whitespace normalization - a second, narrower pass
// specifically for hash stability (Unicode normalization form, line
// -ending normalization, blank-line collapsing, outer trim).
//
// IMPORTANT (spread, not reconstruct): this node spreads the incoming
// item (`...item`) rather than listing fields by hand - NormalizeText's
// own hand-written return object is exactly what silently dropped
// candidate_reference_submitted previously. Spreading here means every
// existing field survives automatically; only the two new hash fields
// are added explicitly.
//
// Pure-JS SHA-256, not crypto/crypto.subtle: this n8n instance runs Code
// nodes through @n8n/task-runner's JsTaskRunner, a separate sandboxed
// vm.createContext() - confirmed by reading js-task-runner.js directly
// that it exposes NO built-in `require()` modules (empty allowedBuiltInModules,
// no relevant env var set) and does NOT inject a `crypto` global either
// (getNativeVariables() only provides Buffer/TextEncoder/TextDecoder/
// FormData/timers - no crypto). Confirmed empirically too: an earlier
// version of this node using `crypto.subtle.digest(...)` failed at
// runtime with "crypto is not defined" (execution 537). The FIPS 180-4
// implementation below was verified against openssl independently
// (SHA256('') and SHA256('abc')) before being used here.

function sha256Hex(bytes) {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];
  let H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const bitLen = bytes.length * 8;
  let paddedLength = bytes.length + 1;
  while (paddedLength % 64 !== 56) paddedLength++;
  paddedLength += 8;
  const padded = new Uint8Array(paddedLength);
  padded.set(bytes);
  padded[bytes.length] = 0x80;
  const highLen = Math.floor(bitLen / 0x100000000);
  const lowLen = bitLen >>> 0;
  const dv = new DataView(padded.buffer);
  dv.setUint32(paddedLength - 8, highLen, false);
  dv.setUint32(paddedLength - 4, lowLen, false);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let chunkStart = 0; chunkStart < paddedLength; chunkStart += 64) {
    const w = new Uint32Array(64);
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(chunkStart + i * 4, false);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i-15], 7) ^ rotr(w[i-15], 18) ^ (w[i-15] >>> 3);
      const s1 = rotr(w[i-2], 17) ^ rotr(w[i-2], 19) ^ (w[i-2] >>> 10);
      w[i] = (w[i-16] + s0 + w[i-7] + s1) >>> 0;
    }
    let [a,b,c,d,e,f,g,h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + temp1) >>> 0;
      d = c; c = b; b = a; a = (temp1 + temp2) >>> 0;
    }
    H[0]=(H[0]+a)>>>0; H[1]=(H[1]+b)>>>0; H[2]=(H[2]+c)>>>0; H[3]=(H[3]+d)>>>0;
    H[4]=(H[4]+e)>>>0; H[5]=(H[5]+f)>>>0; H[6]=(H[6]+g)>>>0; H[7]=(H[7]+h)>>>0;
  }
  return H.map(x => x.toString(16).padStart(8,'0')).join('');
}

const item = $input.first().json;
const rawText = typeof item.resume_text === 'string' ? item.resume_text : '';

const canonical = rawText
  .normalize('NFC')
  .replace(/\r\n?/g, '\n')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const hashHex = sha256Hex(new TextEncoder().encode(canonical));

// === Phase 4a (docs/CANDOR-Hardening-Roadmap-DRAFT.md): near-duplicate
// fingerprint, layered on top of the exact-hash dedup above ===
// A candidate resubmitting a lightly-reformatted resume (different
// whitespace, a reordered sentence, a synonym swap) produces a
// DIFFERENT resume_content_hash - the exact-match dedup above correctly
// does not catch it (by design - it's not byte-identical). This
// fingerprint is a deliberately simple, bounded, transparent v0.1
// heuristic for THAT case: a "bottom-k" sketch of 5-word-shingle hashes
// (a well-known family of near-duplicate detection techniques - not a
// rigorous unbiased MinHash estimator, since that requires comparing
// against the bottom-k of the UNION of two sets, not the two sets'
// bottom-k lists directly; this is a simpler, self-admittedly
// approximate overlap-fraction metric, same "simple, transparent,
// deliberately not exhaustive" discipline as VerifyClaimsAgainstSource's
// own digit-check heuristic). Persists only 20 short hash strings, not
// the shingles or any reconstructable text - privacy-conscious the same
// way Phase 1b's PII-hash redesign was.
function computeShingleFingerprint(text) {
  const words = text.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
  const SHINGLE_SIZE = 5;
  const MIN_HASH_COUNT = 20;
  if (words.length < SHINGLE_SIZE) {
    return [sha256Hex(new TextEncoder().encode(words.join(' ')))];
  }
  const shingleHashes = new Set();
  for (let i = 0; i <= words.length - SHINGLE_SIZE; i++) {
    const shingle = words.slice(i, i + SHINGLE_SIZE).join(' ');
    shingleHashes.add(sha256Hex(new TextEncoder().encode(shingle)));
  }
  return Array.from(shingleHashes).sort().slice(0, MIN_HASH_COUNT);
}

const shingleFingerprint = computeShingleFingerprint(canonical);

// === Phase 6d (docs/CANDOR-Hardening-Roadmap-DRAFT.md): multi-tenant
// scaffolding ===
// A cheap, forward-compatible field added now so a real second tenant
// can be onboarded later without a schema change - not a real
// multi-tenant SYSTEM (there is no tenant registry, no per-tenant
// config, no tenant-scoped credentials). This n8n instance serves
// exactly one tenant today, so the value is a single constant - real
// isolation cannot be verified with only one tenant to test against
// (there is nothing to prove data DOESN'T cross a boundary that has
// never had a second side). Logged as blocked on that precondition in
// docs/CANDOR-Hardening-Build-Log.md Phase 6d, not faked as tested.
const TENANT_ID = 'default-tenant';

return [{
  json: {
    ...item,
    resume_content_hash: hashHex,
    resume_content_hash_algorithm_version: 'v1.0',
    resume_shingle_fingerprint: shingleFingerprint,
    resume_shingle_fingerprint_version: 'CANDOR near-dup shingle-fingerprint v0.1',
    tenant_id: TENANT_ID
  }
}];

// 2026-09-18 (System Review item 12, real-auth half): FormTriggerResumeUpload
// now has Basic Auth configured for real (credential "CANDOR-02 Intake Form
// Basic Auth", n8n httpBasicAuth) - verified both directions on the real live
// form (see CANDOR-02-Build-Log.md): an unauthenticated request now gets a
// real 401 from n8n itself, before this workflow even starts; a correctly
// authenticated request still reaches this node and the rest of the real
// pipeline unchanged. This flag now reflects that real, confirmed state -
// not asserted in passing, checked against the live instance.
const AUTH_CONFIRMED_ENABLED = true;
const SYNTHETIC_DATA_ONLY_OVERRIDE = true; // still true independently: this instance still only ever handles synthetic test fixtures, per Master Instructions §14 - kept true so a real-candidate submission is never silently treated as acceptable just because auth is present.

if (!AUTH_CONFIRMED_ENABLED && !SYNTHETIC_DATA_ONLY_OVERRIDE) {
  throw new Error(
    'CANDOR-02 CheckSecureConfigOverride: refusing to accept this submission. ' +
    'FormTriggerResumeUpload has no confirmed authentication configured, and ' +
    'SYNTHETIC_DATA_ONLY_OVERRIDE is not set. Per CANDOR Master Instructions ' +
    'Section 14, enable authentication on the form trigger before accepting ' +
    'real candidate data, or explicitly set SYNTHETIC_DATA_ONLY_OVERRIDE = true ' +
    'in this node if this is genuinely synthetic test data only.'
  );
}

const items = $input.all();
return items.map(item => ({
  json: {
    ...item.json,
    secure_config_auth_confirmed_enabled: AUTH_CONFIRMED_ENABLED,
    secure_config_synthetic_data_only_override_active: !AUTH_CONFIRMED_ENABLED && SYNTHETIC_DATA_ONLY_OVERRIDE,
    secure_config_check_version: 'CANDOR secure-config fail-fast v0.1'
  },
  binary: item.binary
}));

const AUTH_CONFIRMED_ENABLED = true;
const SYNTHETIC_DATA_ONLY_OVERRIDE = true;

if (!AUTH_CONFIRMED_ENABLED && !SYNTHETIC_DATA_ONLY_OVERRIDE) {
  throw new Error(
    'CANDOR-02 CheckSecureConfigOverrideApplicationForm: refusing to accept this submission. ' +
    'FormTriggerApplicationSubmission has no confirmed authentication configured, and ' +
    'SYNTHETIC_DATA_ONLY_OVERRIDE is not set. Per CANDOR Master Instructions ' +
    'Section 14, enable authentication on the form trigger before accepting ' +
    'real candidate data, or explicitly set SYNTHETIC_DATA_ONLY_OVERRIDE = true ' +
    'in this node if this is genuinely synthetic test data only.'
  );
}

const items = $input.all();
return items.map(item => ({
  json: {
    ...item.json,
    secure_config_auth_confirmed_enabled: AUTH_CONFIRMED_ENABLED,
    secure_config_synthetic_data_only_override_active: !AUTH_CONFIRMED_ENABLED && SYNTHETIC_DATA_ONLY_OVERRIDE,
    secure_config_check_version: 'CANDOR secure-config fail-fast v0.1'
  }
}));

const item = $input.first();
const json = item.json || {};

function trimmed(v) {
  return typeof v === 'string' ? v.trim() : '';
}

const candidateName = trimmed(json.candidate_name);
const contactEmail = trimmed(json.contact_email);
const totalYearsExperience = trimmed(json.total_years_experience);
const keySkills = trimmed(json.key_skills);

function rejected(reason) {
  return [{
    json: {
      candidate_id: null,
      candidate_reference_submitted: trimmed(json.candidate_reference) || null,
      intake_status: 'REJECTED',
      rejection_reason: reason
    }
  }];
}

const missing = [];
if (!candidateName) missing.push('candidate_name');
if (!contactEmail) missing.push('contact_email');
if (!totalYearsExperience) missing.push('total_years_experience');
if (!keySkills) missing.push('key_skills');

if (missing.length > 0) {
  return rejected(`required field(s) missing or empty: ${missing.join(', ')}`);
}

const safeStem = candidateName.replace(/[^a-zA-Z0-9]+/g, '-').toUpperCase().slice(0, 24);
const candidateId = `APPFORM-${safeStem}-${Date.now()}`;

return [{
  json: {
    ...json,
    candidate_id: candidateId,
    candidate_reference_submitted: trimmed(json.candidate_reference) || null,
    intake_status: 'VALID'
  }
}];

// === CANDOR-02 second source adapter: application-form submission ===
//
// ARCHITECTURAL DECISION (stated explicitly, per the build instruction):
// this node builds the full CANDOR-01-shaped "verified candidate
// record" DIRECTLY from the form's own structured fields and calls
// CANDOR-04 directly (CallCANDOR04FromApplicationForm) - it does NOT
// call CANDOR-01's workflow, and no Anthropic extraction call is made
// anywhere on this path. CANDOR-01/CANDOR-04 are both completely
// unmodified by this adapter.
//
// WHY: CANDOR-01's entire job is resolving uncertainty in UNSTRUCTURED
// prose - an LLM infers facts from a resume's free text, and
// VerifyClaimsAgainstSource's literal-quote grounding exists specifically
// to catch the one failure mode that step can introduce: the model
// citing a quote that isn't really in the source (hallucination). A
// candidate typing "7" directly into a "Total Years of Experience" field
// has not been through any inference step at all - there is nothing to
// extract, and therefore nothing that could have been hallucinated. The
// value IS the evidence, by construction. Running the exact same,
// real-money Anthropic call on data that is already unambiguous
// structured input would be pure redundant cost for zero uncertainty
// -reduction benefit - the same reasoning System Review item 43 already
// established for CANDOR-04's JD re-extraction (see
// CANDOR-04-Build-Log.md §27-28): don't pay an LLM to resolve
// uncertainty that doesn't exist.
//
// This node instead reproduces CANDOR-01's OUTPUT SHAPE exactly (the
// same `fields`/`employment_history`/`portfolio_or_work_sample`/
// `verification_summary` contract CANDOR-04's own IntakeCandidateRecord
// already expects and falls back to) so CANDOR-04, CANDOR-05, CANDOR-07,
// and CANDOR-08 all need ZERO changes to accept this new source - this
// is a new intake PATH into the same pipeline, not a new pipeline.
//
// `evidence_verified: true` for a directly-submitted field is not a
// weaker or faked verification - it correctly reports the one specific
// thing that flag has ever meant anywhere in this codebase ("this value
// did not arise from an LLM inventing a quote"), and that claim is
// trivially and honestly true here: there is no LLM step on this path
// at all. It says nothing about whether the candidate told the truth -
// exactly like every other evidence_verified flag in this project, which
// has never verified factual accuracy, only extraction fidelity.
//
// HONEST LIMITATION, stated plainly: quantified_accomplishments and
// notable_unquantified_claims are deliberately left empty - this form
// does not collect freeform accomplishment narrative (classifying free
// text into "quantified" vs "unquantified" claims without an LLM would
// mean reinventing a second, cruder extraction path, which this
// adapter's whole design exists to avoid). Evidence Confidence's
// denominator (verification_summary) is therefore smaller for an
// application-form candidate than a typical resume-derived one (the 8
// scalar fields only, never the 11-15 a resume with several
// accomplishments produces) - a real, structural difference from the
// file-upload path's own reporting depth, not a gamed or inflated score.
// employment_history holds at most ONE entry (the form asks only for the
// candidate's single most recent/most relevant role, not a full career
// history), so career_trajectory's "progression" sub-component (which
// needs >=2 entries) will correctly, honestly report as not-computed for
// every application-form candidate - a real, named scope limit, not a
// bug.

function sha256Hex(bytes) {
  const K = [
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
