    const safeStem = candidateName.replace(/[^a-zA-Z0-9]+/g, '-').toUpperCase().slice(0, 24);
    results.push({
      json: {
        ats_record_index: index,
        record_type: 'DIRECT',
        candidate_id: `ATSEXPORT-${safeStem}-${Date.now()}-${index}`,
        candidate_name: s(record.candidate_name),
