// --- Step 1: repair 'UTF-8 bytes shown as Windows-1252' mojibake ---
// This is the exact corruption pattern that broke CANDOR-01's
// synthetic-resume-03.txt test (see CANDOR-01-Build-Log.md Results, Run 3).
//
// Approach: UTF-8 multi-byte sequences that get mis-decoded one byte at a
// time as Windows-1252 always start with a small, fixed set of lead
// characters - "Ã" (from a 2-byte C3 xx sequence: Latin-1 Supplement
// letters like é/è/ó), "Â" (from a 2-byte C2 xx sequence: C1
// controls/Latin-1 punctuation, most commonly a non-breaking space), and
// "â€" or "â–" (from a 3-byte E2 80/96 xx sequence: General
// Punctuation - curly quotes, dashes, bullet, ellipsis - or Block
// Elements). Each is repaired by reversing exactly that one corrupted
// character back to its original cp1252 BYTE value and reconstructing the
// true Unicode code point via the same UTF-8 bit math, using ONLY the one
// character immediately following the diagnostic prefix. This only fires
// on these specific, essentially never-coincidental 1-2 character prefix
// sequences, so it cannot corrupt a standalone genuine em dash, curly
// quote, or accented letter elsewhere in the text - unlike an earlier
// whole-string approach (reverting the entire text through one byte
// buffer) which was found, via real testing, to corrupt genuinely correct
// em dashes that happened to share a byte-derived code point with actual
// mojibake elsewhere in the same document.
//
// Known, accepted limitation: a small number of cp1252 byte values are
// themselves undefined (e.g. the byte behind a closing curly quote) and
// render as nothing when mis-decoded, so that specific character is
// consumed by nothing 'visible' - the diagnostic prefix is then left
// exactly as-is rather than guessing (a genuine mojibake continuation
// byte is never literal whitespace in practice, so whitespace right
// after the prefix is treated as "not a continuation - leave it alone"
// rather than eaten and replaced with a wrong character). This trades a
// small amount of missed repair for zero risk of silently merging two
// words together or inventing a wrong symbol.
function buildReverseCp1252Map() {
  const highMap = {
    0x80: 0x20AC, 0x82: 0x201A, 0x83: 0x0192, 0x84: 0x201E, 0x85: 0x2026,
    0x86: 0x2020, 0x87: 0x2021, 0x88: 0x02C6, 0x89: 0x2030, 0x8A: 0x0160,
    0x8B: 0x2039, 0x8C: 0x0152, 0x8E: 0x017D, 0x91: 0x2018, 0x92: 0x2019,
    0x93: 0x201C, 0x94: 0x201D, 0x95: 0x2022, 0x96: 0x2013, 0x97: 0x2014,
    0x98: 0x02DC, 0x99: 0x2122, 0x9A: 0x0161, 0x9B: 0x203A, 0x9C: 0x0153,
    0x9E: 0x017E, 0x9F: 0x0178
  };
  const reverseMap = {};
  for (let b = 0; b <= 0xFF; b++) {
    const cp = highMap[b] !== undefined ? highMap[b] : b;
    reverseMap[cp] = b;
  }
  return reverseMap;
}

function repairMojibake(text) {
  if (!text) return { text, repaired: false, repairedCount: 0 };
  const reverseMap = buildReverseCp1252Map();
  let repairedCount = 0;

  function fix(base, nextChar) {
    if (/\s/.test(nextChar)) return null;
    const b = reverseMap[nextChar.codePointAt(0)];
    if (b === undefined) return null;
    return String.fromCodePoint(base | (b & 0x3F));
  }

  let result = text;
  const prefixRules = [['â€', 0x2000], ['â–', 0x2580], ['Ã', 0x00C0], ['Â', 0x0080]];
  for (const [prefix, base] of prefixRules) {
    const re = new RegExp(prefix + '(.)', 'gu');
    result = result.replace(re, (m, c) => {
      const fixed = fix(base, c);
      if (fixed !== null) { repairedCount++; return fixed; }
      return m;
    });
  }

  return { text: result, repaired: repairedCount > 0, repairedCount };
}

