const hashHex = sha256Hex(new TextEncoder().encode(canonical));

// === Phase 4a (docs/CANDOR-Hardening-Roadmap-DRAFT.md): near-duplicate
// fingerprint, layered on top of the exact-hash dedup above ===
// A candidate resubmitting a lightly-reformatted resume (different
// whitespace, a reordered sentence, a synonym swap) produces a
// DIFFERENT resume_content_hash - the exact-match dedup above correctly
// does not catch it (by design - it's not byte-identical). This
// fingerprint is a deliberately simple, bounded, transparent v0.1
// heuristic for THAT case: a "bottom-k" sketch of 5-word-shingle hashes
// (a well-known family of near-duplicate detection techniques - not a
// rigorous unbiased MinHash estimator, since that requires comparing
// against the bottom-k of the UNION of two sets, not the two sets'
// bottom-k lists directly; this is a simpler, self-admittedly
// approximate overlap-fraction metric, same "simple, transparent,
// deliberately not exhaustive" discipline as VerifyClaimsAgainstSource's
// own digit-check heuristic). Persists only 20 short hash strings, not
// the shingles or any reconstructable text - privacy-conscious the same
// way Phase 1b's PII-hash redesign was.
function computeShingleFingerprint(text) {
  const words = text.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
  const SHINGLE_SIZE = 5;
  const MIN_HASH_COUNT = 20;
  if (words.length < SHINGLE_SIZE) {
    return [sha256Hex(new TextEncoder().encode(words.join(' ')))];
  }
  const shingleHashes = new Set();
  for (let i = 0; i <= words.length - SHINGLE_SIZE; i++) {
    const shingle = words.slice(i, i + SHINGLE_SIZE).join(' ');
    shingleHashes.add(sha256Hex(new TextEncoder().encode(shingle)));
