function computeShingleFingerprint(text) {
  const words = text.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
  const SHINGLE_SIZE = 5;
  const MIN_HASH_COUNT = 20;
  if (words.length < SHINGLE_SIZE) {
    return [sha256Hex(new TextEncoder().encode(words.join(' ')))];
  }
  const shingleHashes = new Set();
  for (let i = 0; i <= words.length - SHINGLE_SIZE; i++) {
    const shingle = words.slice(i, i + SHINGLE_SIZE).join(' ');
    shingleHashes.add(sha256Hex(new TextEncoder().encode(shingle)));
  }
  return Array.from(shingleHashes).sort().slice(0, MIN_HASH_COUNT);
}

