    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
  ];
  let H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const bitLen = bytes.length * 8;
  let paddedLength = bytes.length + 1;
  while (paddedLength % 64 !== 56) paddedLength++;
  paddedLength += 8;
  const padded = new Uint8Array(paddedLength);
  padded.set(bytes);
  padded[bytes.length] = 0x80;
  const highLen = Math.floor(bitLen / 0x100000000);
  const lowLen = bitLen >>> 0;
  const dv = new DataView(padded.buffer);
  dv.setUint32(paddedLength - 8, highLen, false);
  dv.setUint32(paddedLength - 4, lowLen, false);
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));
  for (let chunkStart = 0; chunkStart < paddedLength; chunkStart += 64) {
    const w = new Uint32Array(64);
    for (let i = 0; i < 16; i++) w[i] = dv.getUint32(chunkStart + i * 4, false);
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i-15], 7) ^ rotr(w[i-15], 18) ^ (w[i-15] >>> 3);
      const s1 = rotr(w[i-2], 17) ^ rotr(w[i-2], 19) ^ (w[i-2] >>> 10);
      w[i] = (w[i-16] + s0 + w[i-7] + s1) >>> 0;
    }
    let [a,b,c,d,e,f,g,h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e,6) ^ rotr(e,11) ^ rotr(e,25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = rotr(a,2) ^ rotr(a,13) ^ rotr(a,22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + temp1) >>> 0;
      d = c; c = b; b = a; a = (temp1 + temp2) >>> 0;
    }
    H[0]=(H[0]+a)>>>0; H[1]=(H[1]+b)>>>0; H[2]=(H[2]+c)>>>0; H[3]=(H[3]+d)>>>0;
    H[4]=(H[4]+e)>>>0; H[5]=(H[5]+f)>>>0; H[6]=(H[6]+g)>>>0; H[7]=(H[7]+h)>>>0;
  }
  return H.map(x => x.toString(16).padStart(8,'0')).join('');
}

function computeShingleFingerprint(text) {
  const words = text.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/).filter(Boolean);
  const SHINGLE_SIZE = 5;
  const MIN_HASH_COUNT = 20;
  if (words.length < SHINGLE_SIZE) {
    return [sha256Hex(new TextEncoder().encode(words.join(' ')))];
  }
  const shingleHashes = new Set();
  for (let i = 0; i <= words.length - SHINGLE_SIZE; i++) {
    const shingle = words.slice(i, i + SHINGLE_SIZE).join(' ');
    shingleHashes.add(sha256Hex(new TextEncoder().encode(shingle)));
  }
  return Array.from(shingleHashes).sort().slice(0, MIN_HASH_COUNT);
}

function canonicalizeText(text) {
  return (text || '')
    .normalize('NFC')
    .replace(/\r\n?/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function repairMojibake(text) {
  if (!text) return { text, repaired: false, repairedCount: 0 };
  const highMap = {
    0x80: 0x20AC, 0x82: 0x201A, 0x83: 0x0192, 0x84: 0x201E, 0x85: 0x2026,
    0x86: 0x2020, 0x87: 0x2021, 0x88: 0x02C6, 0x89: 0x2030, 0x8A: 0x0160,
    0x8B: 0x2039, 0x8C: 0x0152, 0x8E: 0x017D, 0x91: 0x2018, 0x92: 0x2019,
    0x93: 0x201C, 0x94: 0x201D, 0x95: 0x2022, 0x96: 0x2013, 0x97: 0x2014,
    0x98: 0x02DC, 0x99: 0x2122, 0x9A: 0x0161, 0x9B: 0x203A, 0x9C: 0x0153,
    0x9E: 0x017E, 0x9F: 0x0178
  };
  const reverseMap = {};
  for (let b = 0; b <= 0xFF; b++) {
    const cp = highMap[b] !== undefined ? highMap[b] : b;
    reverseMap[cp] = b;
  }
  let repairedCount = 0;
  function fix(base, nextChar) {
    if (/\s/.test(nextChar)) return null;
    const b = reverseMap[nextChar.codePointAt(0)];
    if (b === undefined) return null;
    return String.fromCodePoint(base | (b & 0x3F));
  }
  let result = text;
  const prefixRules = [['â€', 0x2000], ['â–', 0x2580], ['Ã', 0x00C0], ['Â', 0x0080]];
  for (const [prefix, base] of prefixRules) {
    const re = new RegExp(prefix + '(.)', 'gu');
    result = result.replace(re, (m, c) => {
      const fixed = fix(base, c);
      if (fixed !== null) { repairedCount++; return fixed; }
      return m;
    });
  }
  return { text: result, repaired: repairedCount > 0, repairedCount };
}

function stripReplacementChars(text) {
  const count = (text.match(/�/g) || []).length;
  return { text: text.replace(/�/g, ''), count };
}

function normalizeWhitespace(text) {
  return text
    .replace(/ /g, ' ')
    .replace(/\r\n?/g, '\n')
    .split('\n')
    .map(line => line.replace(/[ \t]+/g, ' ').trimEnd())
    .join('\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function s(v) {
  return typeof v === 'string' ? v.trim() : '';
}

const REQUIRED_DIRECT_FIELDS = ['candidate_name', 'contact_email', 'total_years_experience', 'key_skills'];

const item = $input.first().json;
let envelope;
try {
  envelope = JSON.parse(item.ats_export_text || '');
} catch (e) {
  throw new Error(`CANDOR-02 ParseAndClassifyATSExportBatch: the uploaded ATS export file is not valid JSON - refusing the whole batch (no per-record recovery is possible when the file's own structure can't be parsed). Parse error: ${e.message}`);
}

if (!envelope || typeof envelope !== 'object' || Array.isArray(envelope) || !Array.isArray(envelope.candidates)) {
  throw new Error('CANDOR-02 ParseAndClassifyATSExportBatch: the uploaded ATS export file does not have the expected shape - a JSON object with a top-level "candidates" array. Refusing the whole batch.');
}

const seenHashes = new Set();
const results = [];

envelope.candidates.forEach((record, index) => {
  try {
    if (!record || typeof record !== 'object' || Array.isArray(record)) {
      results.push({ json: { ats_record_index: index, record_type: 'MALFORMED', rejection_reason: `record is not a JSON object (got ${record === null ? 'null' : Array.isArray(record) ? 'array' : typeof record})` } });
      return;
    }

    const candidateName = s(record.candidate_name);
    if (!candidateName) {
      results.push({ json: { ats_record_index: index, record_type: 'MALFORMED', rejection_reason: 'candidate_name missing or empty' } });
      return;
    }

    const rawResumeText = typeof record.resume_text === 'string' ? record.resume_text : '';
    const hasResumeText = rawResumeText.trim().length > 0;

    if (hasResumeText) {
      const step1 = repairMojibake(rawResumeText);
      const step2 = stripReplacementChars(step1.text);
      const finalText = normalizeWhitespace(step2.text);
      const canonical = canonicalizeText(finalText);
      const hash = sha256Hex(new TextEncoder().encode(canonical));

      if (seenHashes.has(hash)) {
        results.push({ json: { ats_record_index: index, record_type: 'IN_BATCH_DUPLICATE', candidate_name: candidateName, resume_content_hash: hash, rejection_reason: 'identical resume_text already seen earlier in this same batch - skipped before any Anthropic call was made' } });
        return;
      }
      seenHashes.add(hash);

      const safeStem = candidateName.replace(/[^a-zA-Z0-9]+/g, '-').toUpperCase().slice(0, 24);
      results.push({
        json: {
          ats_record_index: index,
          record_type: 'NEEDS_EXTRACTION',
          candidate_id: `ATSEXPORT-${safeStem}-${Date.now()}-${index}`,
          resume_filename: 'ATS_EXPORT_RECORD',
          resume_text: finalText,
          resume_content_hash: hash,
          resume_content_hash_algorithm_version: 'v1.0',
          resume_shingle_fingerprint: computeShingleFingerprint(canonical),
          resume_shingle_fingerprint_version: 'CANDOR near-dup shingle-fingerprint v0.1',
          tenant_id: 'default-tenant',
          intake_source: 'ats_export',
          ats_candidate_id_submitted: record.ats_candidate_id ?? null,
          normalization_notes: {
            mojibake_repair_applied: step1.repaired,
            mojibake_repairs_count: step1.repairedCount,
            replacement_chars_stripped: step2.count
          }
        }
      });
      return;
    }

    const missing = REQUIRED_DIRECT_FIELDS.filter(f => !s(record[f]));
    if (missing.length > 0) {
      results.push({ json: { ats_record_index: index, record_type: 'MALFORMED', candidate_name: candidateName, rejection_reason: `neither resume_text nor the required direct fields are all present - missing: ${missing.join(', ')}` } });
      return;
    }

    const canonicalFieldBlob = [
      `Candidate Name: ${s(record.candidate_name)}`,
      `Contact Email: ${s(record.contact_email)}`,
      `Total Years of Experience: ${s(record.total_years_experience)}`,
      `Key Skills: ${s(record.key_skills)}`,
      `Most Recent Title: ${s(record.most_recent_title)}`,
      `Most Recent Employer: ${s(record.most_recent_employer)}`,
      `Years in Most Recent Role: ${s(record.years_in_role)}`,
      `Education: ${s(record.education)}`,
      `Certifications: ${s(record.certifications)}`,
      `Portfolio or Work Sample: ${s(record.portfolio_url)}`
    ].join('\n');
    const canonical = canonicalizeText(canonicalFieldBlob);
    const hash = sha256Hex(new TextEncoder().encode(canonical));

    if (seenHashes.has(hash)) {
      results.push({ json: { ats_record_index: index, record_type: 'IN_BATCH_DUPLICATE', candidate_name: candidateName, resume_content_hash: hash, rejection_reason: 'identical structured-field content already seen earlier in this same batch' } });
      return;
    }
    seenHashes.add(hash);

    const safeStem = candidateName.replace(/[^a-zA-Z0-9]+/g, '-').toUpperCase().slice(0, 24);
    results.push({
      json: {
        ats_record_index: index,
        record_type: 'DIRECT',
        candidate_id: `ATSEXPORT-${safeStem}-${Date.now()}-${index}`,
        candidate_name: s(record.candidate_name),
        contact_email: s(record.contact_email),
        total_years_experience: s(record.total_years_experience),
        key_skills: s(record.key_skills),
        most_recent_title: s(record.most_recent_title),
        most_recent_employer: s(record.most_recent_employer),
        years_in_role: s(record.years_in_role),
        education: s(record.education),
        certifications: s(record.certifications),
        portfolio_url: s(record.portfolio_url),
        resume_content_hash: hash,
        resume_content_hash_algorithm_version: 'v1.0',
        resume_shingle_fingerprint: computeShingleFingerprint(canonical),
        resume_shingle_fingerprint_version: 'CANDOR near-dup shingle-fingerprint v0.1',
        tenant_id: 'default-tenant',
        intake_source: 'ats_export',
        ats_candidate_id_submitted: record.ats_candidate_id ?? null
      }
    });
  } catch (recordError) {
    results.push({ json: { ats_record_index: index, record_type: 'MALFORMED', rejection_reason: `unexpected error while processing this record: ${recordError.message}` } });
  }
});

return results;

const INJECTION_PATTERNS = [
  { label: 'ignore_prior_instructions', re: /ignore\s+(all\s+)?(the\s+)?(previous|prior|above|earlier)\s+instructions?/i },
  { label: 'disregard_prior_instructions', re: /disregard\s+(all\s+)?(the\s+)?(previous|prior|above|earlier)\s+instructions?/i },
  { label: 'new_instructions_marker', re: /\bnew\s+instructions?\s*[:.]/i },
  { label: 'you_are_now', re: /\byou\s+are\s+now\s+(a|an|the)\b/i },
  { label: 'system_prompt_reference', re: /\bsystem\s+prompt\b/i },
  { label: 'rate_all_skills_as_expert', re: /rate\s+(all|every|each)\s+skills?\s+as\s+(expert|10\s*\/\s*10|maximum|top)/i },
  { label: 'act_as_persona', re: /\bact\s+as\s+(a|an)\s+/i },
  { label: 'do_not_follow_rules_above', re: /do\s+not\s+(follow|apply)\s+the\s+(rules|instructions)\s+above/i },
  { label: 'assistant_role_injection', re: /\b(assistant|ai)\s*:\s*(ignore|okay|sure|understood)/i }
];

function detectInjection(text) {
  const t = (text || '').toString();
  const matched = INJECTION_PATTERNS.filter(p => p.re.test(t)).map(p => p.label);
  return { suspected: matched.length > 0, matched };
}

const item = $input.first().json;

function s(v) {
  return typeof v === 'string' ? v.trim() : '';
}

const candidateName = s(item.candidate_name);
const contactEmail = s(item.contact_email);
const totalYearsExperienceText = s(item.total_years_experience);
const keySkillsText = s(item.key_skills);
const mostRecentTitle = s(item.most_recent_title);
const mostRecentEmployer = s(item.most_recent_employer);
const yearsInRole = s(item.years_in_role);
const education = s(item.education);
const certifications = s(item.certifications);
const portfolioUrl = s(item.portfolio_url);

function directField(fieldName, rawValue, displayValue) {
  const value = displayValue !== undefined ? displayValue : rawValue;
  if (!rawValue) {
    return { field: fieldName, value: 'insufficient information', source_quote: '', evidence_verified: false, reason: 'field not provided on the ATS export record' };
  }
  const quote = Array.isArray(value) ? value.join(', ') : String(value);
  return { field: fieldName, value, source_quote: quote, evidence_verified: true, reason: 'directly submitted via the CANDOR-02 ATS-export adapter (structured record, no resume text) - no extraction step, so no hallucination risk to check for' };
}

function yearsSourceQuote(yearsText, skillsText) {
  const parts = [`${yearsText} years of experience`];
  if (skillsText) parts.push(`with skills including ${skillsText}`);
  return parts.join(' ');
}

const keySkillsArray = keySkillsText
  ? keySkillsText.split(',').map(sVal => sVal.trim()).filter(Boolean)
  : [];

const fields = [
  directField('candidate_name', candidateName),
  directField('contact_email', contactEmail),
  (totalYearsExperienceText
    ? { field: 'total_years_experience_claimed', value: totalYearsExperienceText, source_quote: yearsSourceQuote(totalYearsExperienceText, keySkillsText), evidence_verified: true, reason: 'directly submitted via the CANDOR-02 ATS-export adapter - source_quote synthesized from this same record\'s own key_skills field (an already-permitted field, never an excluded one) so CalculateMatchScore\'s domain-relevance gate has real vocabulary to check, not just a bare number' }
    : { field: 'total_years_experience_claimed', value: 'insufficient information', source_quote: '', evidence_verified: false, reason: 'field not provided on the ATS export record' }),
  directField('most_recent_title', mostRecentTitle),
  directField('most_recent_employer', mostRecentEmployer),
  directField('key_skills', keySkillsText, keySkillsArray),
  directField('education', education),
  directField('certifications', certifications)
];

const verifiedCount = fields.filter(f => f.evidence_verified).length;

let employmentHistory = [];
if (mostRecentTitle || mostRecentEmployer || yearsInRole) {
  const durationText = /^\d+(\.\d+)?$/.test(yearsInRole) ? `${yearsInRole} years` : (yearsInRole || 'insufficient information');
  const hasDuration = durationText !== 'insufficient information';
  employmentHistory = [{
    field: 'employment_history[0]',
    title: mostRecentTitle || 'insufficient information',
    employer: mostRecentEmployer || 'insufficient information',
    duration_text: durationText,
    source_quote: hasDuration ? durationText : '',
    evidence_verified: hasDuration,
    title_verified: !!mostRecentTitle,
    employer_verified: !!mostRecentEmployer,
    reason: hasDuration
      ? 'directly submitted via the CANDOR-02 ATS-export adapter - no extraction step, so no hallucination risk to check for'
      : 'years in this role not provided on the ATS export record'
  }];
}

const portfolioOrWorkSample = directField('portfolio_or_work_sample', portfolioUrl);

const injectionCheck = detectInjection([candidateName, contactEmail, mostRecentTitle, mostRecentEmployer, keySkillsText, education, certifications, portfolioUrl].join(' \n '));

return [{
  json: {
    candidate_id: item.candidate_id,
    resume_filename: 'ATS_EXPORT_RECORD',
    intake_source: 'ats_export',
    ats_candidate_id_submitted: item.ats_candidate_id_submitted ?? null,
    extraction_status: 'PARSED_OK',
    resume_content_hash: item.resume_content_hash,
    resume_content_hash_algorithm_version: item.resume_content_hash_algorithm_version,
    resume_shingle_fingerprint: item.resume_shingle_fingerprint,
    resume_shingle_fingerprint_version: item.resume_shingle_fingerprint_version,
    tenant_id: item.tenant_id,
    processed_at: new Date().toISOString(),
    model_used: 'direct_ats_export_entry (no Anthropic call on this path - structured record, no resume text)',
    prompt_injection_suspected: injectionCheck.suspected,
    prompt_injection_matched_patterns: injectionCheck.matched,
    prompt_injection_check_version: 'CANDOR prompt-injection pattern-flag v0.1',
    fields,
    quantified_accomplishments: [],
    notable_unquantified_claims: [],
    employment_history: employmentHistory,
    portfolio_or_work_sample: portfolioOrWorkSample,
    verification_summary: {
      total_items_checked: fields.length,
      evidence_verified_count: verifiedCount,
      not_verified_count: fields.length - verifiedCount
    }
  }
}];
